#[verus]
fn solve(input: Vec<char>) -> Vec<char> {
    // Ensure that the input length is at least 2
    assert!(input.len() >= 2);
    
    // Extract the first two characters
    let first_digit = input[0];
    let second_digit = input[1];

    // Ensure that the first two characters are ASCII decimal digits
    assert!(first_digit >= '0' && first_digit <= '9');
    assert!(second_digit >= '0' && second_digit <= '9');

    // Define the good count mapping
    let good_count = |c: char| {
        match c {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // This case should not occur due to previous assertions
        }
    };

    // Compute the good counts
    let count1 = good_count(first_digit);
    let count2 = good_count(second_digit);

    // Compute the product
    let product = count1 * count2;

    // Ensure the product is within the expected range
    assert!(product >= 1 && product <= 49);

    // Convert the product to a string representation
    let product_str = product.to_string();

    // Create the output vector
    let mut output = Vec::new();

    // Append the product characters to the output
    for c in product_str.chars() {
        output.push(c);
    }

    // Append the newline character
    output.push('\n');

    // Ensure the output contains only digit characters and a newline
    assert!(output.len() > 0);
    assert!(output[output.len() - 1] == '\n');
    for i in 0..output.len() - 1 {
        assert!(output[i] >= '0' && output[i] <= '9');
    }

    output
}